def handle(args, state, ds):
    report = ds.consistency_report()
    pending = report.get("pending", 0)
    checked = report.get("checked", 0)
    if pending == 0:
        return {
            "status": "complete",
            "sla_timers_final": True,
            "timers_checked": checked,
            "timers_pending_recalculation": 0,
            "detail": "All incident SLA timers have settled into a definitive state (within_target or breached)."
        }
    return {
        "status": "in_progress",
        "sla_timers_final": False,
        "timers_checked": checked,
        "timers_pending_recalculation": pending,
        "detail": "SLA timer recalculations are still propagating across SLA engine clusters."
    }

